#include <iostream>
#include <vector>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, k, l;
    cin >> n >> k >> l;
    const long long MOD = 998244353;

    vector<long long> factorial(n + 1, 1);
    for (int i = 1; i <= n; i++) {
        factorial[i] = (factorial[i - 1] * i) % MOD;
    }

    vector<vector<long long>> dp(2 * n + 1, vector<long long>(2 * n + 2, 0));
    dp[0][0] = 1;

    for (int i = 1; i <= 2 * n; i++) {
        for (int j = 0; j <= i; j++) {
            if (j > 0) {
                dp[i][j] = (dp[i][j] + dp[i - 1][j - 1]) % MOD;
            }
            if (j + 1 <= 2 * n + 1) {
                dp[i][j] = (dp[i][j] + dp[i - 1][j + 1] * (j + 1) % MOD) % MOD;
            }
        }
    }

    auto power = [&](long long base, int exp) -> long long {
        long long res = 1;
        long long b = base % MOD;
        int e = exp;
        while (e > 0) {
            if (e & 1) res = (res * b) % MOD;
            b = (b * b) % MOD;
            e >>= 1;
        }
        return res;
    };

    long long total = 0;
    for (int i = k; i <= 2 * n; i++) {
        for (int j = k; j <= n; j++) {
            long long term = (dp[i][j] * dp[2 * n - i][j]) % MOD;
            term = (term * factorial[j]) % MOD;
            total = (total + term) % MOD;
        }
    }

    long long invA = power(dp[2 * n][0], MOD - 2);
    long long invB = power(2 * n + 1, MOD - 2);
    long long answer = (l % MOD) * total % MOD * invA % MOD * invB % MOD;

    cout << answer << "\n";

    return 0;
}
